import { createMemo, createTrackedEffect } from "solid-js";

export function hand(fn) {
  createTrackedEffect(() => {
    fn();
  });
}

export function handMemo(fn) {
  createMemo(() => {
    fn();
    return 0;
  });
}

export function handTwice(fn) {
  createTrackedEffect(() => {
    fn();
  });
  setTimeout(fn, 0);
}
